CREATE POLICY "view_subscriptions_own_update" ON "view_subscriptions" AS RESTRICTIVE FOR UPDATE USING ("user_id" = app.current_user_id()) WITH CHECK ("user_id" = app.current_user_id());--> statement-breakpoint
